-- Synthetic test schema copied from production column metadata on 2026-09-13; no customer data.
create schema auth;
create role anon; create role authenticated; create role service_role; create role hermes_operator;
create table auth.users(id uuid primary key);
create table public.user_profiles (
 "id" uuid not null primary key,
 "email" text,
 "company_name" text,
 "country" text default 'NL'::text,
 "kvk_kbo" text,
 "btw_nr" text,
 "address" text,
 "iban" text,
 "peppol_id" text,
 "plan" text default 'free'::text,
 "credits" int4 default 3,
 "onboarding_complete" bool default false,
 "created_at" timestamptz default now(),
 "postal_code" text,
 "city" text,
 "recommand_company_id" text,
 "recommand_verified" bool default false not null,
 "recommand_verification_url" text,
 "recommand_raw_response" jsonb,
 "send_credits" int4 default 0 not null,
 "send_credits_expires_at" timestamptz,
 "is_admin" bool default false not null,
 "address_verified" bool default false not null,
 "address_validation_source" text,
 "vat_validation_status" text default 'unchecked'::text not null,
 "vat_validated_at" timestamptz
);
create table public.payments (
 "id" uuid default gen_random_uuid() not null primary key,
 "user_id" uuid,
 "type" text,
 "mollie_payment_id" text,
 "amount" numeric,
 "credits" int4 default 0,
 "status" text default 'open'::text,
 "created_at" timestamptz default now(),
 "mollie_customer_id" text,
 "mollie_subscription_id" text,
 "mollie_mandate_id" text,
 "sequence_type" text,
 "plan" text,
 "metadata" jsonb,
 "mollie_mode" text
);
create table public.invoices (
 "id" uuid default gen_random_uuid() not null primary key,
 "user_id" uuid not null,
 "client_id" uuid,
 "invoice_number" text not null,
 "invoice_date" date not null,
 "due_date" date,
 "currency" text default 'EUR'::text,
 "status" text default 'draft'::text,
 "ubl_xml" text,
 "total_excl" numeric,
 "vat_total" numeric,
 "total_incl" numeric,
 "peppol_message_id" text,
 "sent_at" timestamptz,
 "created_at" timestamptz default now(),
 "subscription_id" uuid,
 "payment_id" uuid,
 "amount" numeric,
 "vat_amount" numeric,
 "vat_rate" numeric default 21,
 "issued_at" timestamptz,
 "invoice_kind" text default 'sales'::text not null,
 "original_invoice_id" uuid,
 "original_invoice_number" text,
 "recommand_document_id" text,
 "recommand_status" text,
 "recommand_raw_response" jsonb,
 "verified_recipient" bool default false not null,
 "sent_via_recommand_at" timestamptz,
 "recommand_claimed_at" timestamptz,
 "payment_method" text,
 "paid_at" timestamptz,
 "delivered_at" date,
 "pdf_path" text,
 "admin_pdf_path" text,
 "pdf_stored_at" timestamptz,
 "pdf_retention_until" timestamptz,
 "legal_supplier_name" text,
 "legal_supplier_address" text,
 "legal_supplier_postal_code" text,
 "legal_supplier_city" text,
 "legal_supplier_country" text,
 "legal_supplier_vat_id" text,
 "legal_supplier_kvk" text,
 "email_status" text default 'pending'::text not null,
 "brevo_message_id" text,
 "email_accepted_at" timestamptz,
 "email_delivered_at" timestamptz,
 "email_error" text
);
alter table public.user_profiles add foreign key(id) references auth.users(id) on delete cascade;
alter table public.payments add foreign key(user_id) references auth.users(id) on delete cascade;
alter table public.invoices add constraint invoices_user_id_fkey foreign key(user_id) references auth.users(id) on delete cascade;
alter table public.invoices add constraint invoices_payment_id_fkey foreign key(payment_id) references public.payments(id) on delete set null;
